# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Billing fence on mobile collection create between commit and link creation", type: :request do
  # "Also cover handoff starting after collection commit but before link creation, then retry the same idempotency key without duplicating the collection."
  it "keeps one collection and creates one payment link when a handoff starts between the collection commit and link creation and the same idempotency key is retried twice" do
    company = create(:india_company, base_currency: "INR", plan_tier: "paid")
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
    provider = build(
      :payments_provider,
      company:,
      name: PaymentsProvider::RAZORPAY_PROVIDER,
      connected: true,
      enabled: true,
      accepted_payment_methods: ["razorpay"],
      settings: { enabled_on_invoices: true, key_id: "rzp_test_123", sms_notifications_enabled: true }
    )
    provider.key_secret = "secret"
    provider.save!

    razorpay_client = instance_double(PaymentProviders::RazorpayClient)
    allow(PaymentProviders::RazorpayClient).to receive(:new).and_return(razorpay_client)
    allow(razorpay_client).to receive(:create_payment_link).and_return(
      { "id" => "plink_mid_handoff_1", "short_url" => "https://rzp.io/rzp/mid-handoff", "status" => "created" }
    )
    allow(razorpay_client).to receive(:fetch_payment_link).and_return({ "status" => "created" })

    # The handoff must begin after the collection's own fenced transaction has
    # committed, so it is started when the controller builds the link service.
    handoff_started = false
    allow(PaymentProviders::RazorpayPaymentLinkService).to receive(:new).and_wrap_original do |original, **kwargs|
      unless handoff_started
        handoff_started = true
        TimekeepingOwnership.current.update!(handoff_step: "close_admission")
      end
      original.call(**kwargs)
    end

    key = "mid-handoff-link-key-1"
    params = { collection: { amount: "1800", name: "Kavya Rao", phone: "+91 98111 55667", create_payment_link: true, idempotency_key: key } }
    keyed_invoices = -> { Invoice.where("payment_infos ->> 'mobile_collection_idempotency_key' = ?", key) }

    post "/api/v1/mobile/collections", params:, headers: auth_headers(user)

    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(razorpay_client).not_to have_received(:create_payment_link)
    expect(keyed_invoices.call.count).to eq(1)
    committed_invoice = keyed_invoices.call.first
    expect(committed_invoice.razorpay_payment_link_id).to be_nil
    expect(committed_invoice.razorpay_payment_link_url).to be_nil
    counts_after_refusal = [Client.count, Invoice.count, Payment.count]

    TimekeepingOwnership.current.update!(handoff_step: nil)
    post "/api/v1/mobile/collections", params:, headers: auth_headers(user)

    expect(response).to have_http_status(:ok)
    expect([Client.count, Invoice.count, Payment.count]).to eq(counts_after_refusal)
    expect(keyed_invoices.call.count).to eq(1)
    expect(committed_invoice.reload.razorpay_payment_link_id).to eq("plink_mid_handoff_1")
    expect(committed_invoice.razorpay_payment_link_url).to eq("https://rzp.io/rzp/mid-handoff")

    # A client that did not see the first success sends the same key again.
    post "/api/v1/mobile/collections", params:, headers: auth_headers(user)

    expect(response).to have_http_status(:ok)
    expect([Client.count, Invoice.count, Payment.count]).to eq(counts_after_refusal)
    expect(keyed_invoices.call.count).to eq(1)
    expect(razorpay_client).to have_received(:create_payment_link).once
    expect(committed_invoice.reload.razorpay_payment_link_id).to eq("plink_mid_handoff_1")
  end
end

RSpec.describe "Billing fence on mobile collection manual payment retries", type: :request do
  # "Check the response, unchanged payment and invoice data, and absence of a provider creation call."
  it "records exactly one payment when a manual payment refused during a handoff is resent twice after the handoff ends" do
    company = create(:india_company, base_currency: "INR", plan_tier: "paid")
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
    client = create(:client, company:, currency: "INR")
    invoice = create(
      :invoice,
      company:,
      client:,
      amount_value: 2400,
      currency: "INR",
      status: :sent,
      payment_infos: { mobile_collection_source: "mobile" }
    )
    invoice.reload
    baseline = {
      payments: Payment.count,
      status: invoice.status,
      amount_paid: invoice.amount_paid,
      amount_due: invoice.amount_due,
      payment_infos: invoice.payment_infos
    }
    expect(baseline[:status]).to eq("sent")
    expect(baseline[:amount_due]).to be > 0
    params = { collection: { payment_method: "cash" } }

    TimekeepingOwnership.current.update!(handoff_step: "close_admission")
    post "/api/v1/mobile/collections/#{invoice.id}/manual_payment", params:, headers: auth_headers(user)

    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    invoice.reload
    expect(
      payments: Payment.count,
      status: invoice.status,
      amount_paid: invoice.amount_paid,
      amount_due: invoice.amount_due,
      payment_infos: invoice.payment_infos
    ).to eq(baseline)

    TimekeepingOwnership.current.update!(handoff_step: nil)
    post "/api/v1/mobile/collections/#{invoice.id}/manual_payment", params:, headers: auth_headers(user)

    expect(response).to have_http_status(:ok)
    expect(Payment.count).to eq(baseline[:payments] + 1)

    # The collector's app may resend the same request after a timeout.
    post "/api/v1/mobile/collections/#{invoice.id}/manual_payment", params:, headers: auth_headers(user)

    expect(response).to have_http_status(:unprocessable_content)
    expect(Payment.count).to eq(baseline[:payments] + 1)
    expect(invoice.reload).to be_paid
  end
end

